/*
 * The API contract the SDK is checked against: generated by the app (the
 * price repo, `npm run contract:generate` there → contract/api-contract.json)
 * from the code that builds real responses, and copied here by
 * `npm run sync:contract`. Never edit contract/ or tests/contract/ by hand.
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const SDK_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
/** The app's checkout: a sibling folder by default, or PRICE_REPO. */
export const PRICE_ROOT = path.resolve(process.env.PRICE_REPO ?? path.join(SDK_ROOT, "..", "price"));

export const APP_CONTRACT = path.join(PRICE_ROOT, "contract", "api-contract.json");
export const CONTRACT_COPY = path.join(SDK_ROOT, "contract", "api-contract.json");
export const FIXTURES = path.join(SDK_ROOT, "tests", "contract", "fixtures.generated.ts");

export type ContractExample = { name: string; request: Record<string, unknown>; status: number; response: unknown };
export type ContractErrorExample = { name: string; status: number; headers: Record<string, string>; body: unknown };

export type ApiContract = {
    contract_version: number;
    match_reasons: string[];
    warning_codes: string[];
    pricing_modes: string[];
    rule_types: string[];
    skip_reasons: string[];
    customer_target_types: string[];
    product_target_types: string[];
    error_codes: { code: string; status: number }[];
    examples: {
        resolve: ContractExample[];
        resolve_bulk: ContractExample[];
        errors: ContractErrorExample[];
    };
};

/** Line endings normalized so Windows checkouts (autocrlf) don't read as drift. */
export const lf = (text: string) => text.replace(/\r\n/g, "\n");

export function readText(file: string): string | null {
    try {
        return lf(readFileSync(file, "utf8"));
    } catch {
        return null;
    }
}

const literal = (value: unknown) => JSON.stringify(value, null, 4).replace(/\n/g, "\n    ");

/**
 * tests/contract/fixtures.generated.ts for a contract: every example written
 * out as an object literal typed with the SDK's own types, so `tsc` fails on
 * a field the SDK lacks (an excess property), one it requires that the API
 * no longer sends, or a value of the wrong type.
 */
export function fixturesSource(contract: ApiContract): string {
    const examples = (type: string, list: { name: string; value: unknown }[]) =>
        `[\n${list.map(({ name, value }) => `    {\n        name: ${JSON.stringify(name)},\n        value: ${literal(value).replace(/\n/g, "\n    ")} satisfies ${type},\n    },`).join("\n")}\n]`;

    return `// GENERATED by \`npm run sync:contract\` from contract/api-contract.json: do not edit.
// Typed with the SDK's own types: \`npm run typecheck\` fails when they drift from the API.
import type { ErrorResponse, ResolveBulkResponse, ResolveResponse } from "../../src/index";

export const resolveResponses = ${examples("ResolveResponse", contract.examples.resolve.map((e) => ({ name: e.name, value: e.response })))};

export const resolveBulkResponses = ${examples("ResolveBulkResponse", contract.examples.resolve_bulk.map((e) => ({ name: e.name, value: e.response })))};

export const errorResponses = ${examples("ErrorResponse", contract.examples.errors.map((e) => ({ name: e.name, value: e.body })))};
`;
}
